const ID_NAMES: ReadonlyMap<number, string> = new Map([...ID_VALUES].map(([name, value]) => [value, name]));

/** The ID value of an ID name; 0 when there is none. */
export function find_id_value(id_name: string): number {
  return ID_VALUES.get(id_name) ?? 0;
}

/** The ID name of an ID value; an empty string when there is none. */
export function find_id_name(id_value: number): string {
  return ID_NAMES.get(id_value) ?? "";
}
